import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Kiosque self-service","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/09-kiosk.md","filePath":"generated/modules/09-kiosk.md","lastUpdated":null}'),n={name:"modules/09-kiosk.md"};function r(o,a,i,p,l,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="kiosque-self-service" tabindex="-1">Kiosque self-service <a class="header-anchor" href="#kiosque-self-service" aria-label="Permalink to &quot;Kiosque self-service&quot;">​</a></h1><p><span class="badge todo">À faire</span> <span class="muted">Phase 4 · <a href="/VendoraSystem-docs/specs/09-kiosk">spécification complète</a></span></p><p>Borne de commande verrouillée sur tablette : parcours client brandé, paiement au terminal ou au comptoir, numéro de retrait, routage cuisine identique aux commandes de salle, supervision au back-office. L&#39;app kiosque est prévue en phase 4 et n&#39;est pas commencée ; seule la configuration est prête (presets kiosque versionnés et preset par appareil au lot 2.25, filtrage du hub pour le rôle KIOSK au lot 2.26).</p><div class="kpis"><div><b>3</b><span>faites</span></div><div><b>2</b><span>partielles</span></div><div><b>19</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Presets kiosque du magasin</strong><br><span class="muted">L&#39;owner publie au back-office des presets versionnés : écran d&#39;accueil, mode de paiement, validation manuelle, étape sur place / à emporter, délai d&#39;inactivité, produits mis en avant.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-04, RG-KIOSK-05, RG-KIOSK-09, RG-THEME-14</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Preset assigné à chaque appareil</strong><br><span class="muted">La configuration par appareil porte <code>kioskPresetId</code> (422 si inconnu), diffusée par <code>DeviceConfigUpdated</code> et <code>KioskPresetUpdated</code> jusqu&#39;au miroir local.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-THEME-14</td><td>2.22, 2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Bannières promotionnelles</strong><br><span class="muted">Le preset porte des bannières (titre, cible, période de validité) qui disparaissent d&#39;elles-mêmes à expiration.<br><i>Titres et validité configurés ; téléversement des images de bannière et de l&#39;écran d&#39;accueil à faire.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td>RG-THEME-14</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr><tr><td><strong>Multilingue</strong><br><span class="muted">Les langues fr / en / ar (avec RTL) sont résolues appareil &gt; magasin ; le kiosque doit offrir un sélecteur de langue sur tous ses écrans.<br><i>Traductions limitées aux écrans cœur des caisses ; aucun écran kiosque ni sélecteur client (phase 4).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td>RG-KIOSK-13, RG-THEME-12</td><td>2.25</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-personnalisation">📷</a></td></tr></tbody></table><h2 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Filtrage du hub pour le rôle KIOSK</strong><br><span class="muted">Le hub local ne relaie au kiosque que le catalogue et sa configuration, rattrapage compris.<br><i>Couvert par les tests du hub (<code>HubRouting</code>), sans appareil kiosque réel.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-10</td><td>2.26</td><td></td></tr><tr><td><strong>Commandes kiosque sans internet</strong><br><span class="muted">Sans internet, le kiosque continue en paiement au comptoir via le hub local ; sans hub ni imprimante, il passe en « Borne momentanément indisponible ».<br><i>Phase 4 ; s&#39;appuiera sur le hub local livré au lot 2.6.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-10</td><td></td><td></td></tr></tbody></table><h2 id="mode-verrouille-securite" tabindex="-1">Mode verrouillé &amp; sécurité <a class="header-anchor" href="#mode-verrouille-securite" aria-label="Permalink to &quot;Mode verrouillé &amp; sécurité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Mode kiosque verrouillé</strong><br><span class="muted">L&#39;app tourne épinglée (Lock Task Mode Android, Guided Access / Single App Mode iPad) et ne se quitte qu&#39;avec un code de déverrouillage.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-01</td><td></td><td></td></tr><tr><td><strong>Permissions restreintes du rôle KIOSK</strong><br><span class="muted">Un jeton KIOSK crée des commandes et imprime, mais remise, retour, tiroir ou rapports répondent 403 FORBIDDEN_FOR_DEVICE_ROLE (tentative tracée).<br><i>Phase 4 ; le rôle d&#39;appareil KIOSK existe côté serveur mais aucune restriction dédiée n&#39;est livrée.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-02</td><td></td><td></td></tr></tbody></table><h2 id="parcours-client" tabindex="-1">Parcours client <a class="header-anchor" href="#parcours-client" aria-label="Permalink to &quot;Parcours client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Accueil brandé</strong><br><span class="muted">Écran d&#39;accueil au thème du magasin (logo, couleurs, titre du preset), tap pour commencer, langue par défaut configurée.<br><i>Phase 4 ; le thème, le logo et le titre d&#39;accueil du preset sont déjà transportés jusqu&#39;aux appareils.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-13</td><td>2.25</td><td></td></tr><tr><td><strong>Choix sur place / à emporter</strong><br><span class="muted">Étape obligatoire pour un restaurant, pouvant changer la TVA ; masquée pour les autres profils.<br><i>Phase 4 ; le réglage <code>fulfillmentChoice</code> existe dans le preset (lot 2.25).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-04</td><td></td><td></td></tr><tr><td><strong>Catalogue filtré pour le kiosque</strong><br><span class="muted">Seuls les produits <code>availableOnKiosk</code> et non en rupture sont affichés, prix TTC non modifiables, catégories mises en avant.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-12</td><td></td><td></td></tr><tr><td><strong>Fiche produit avec modificateurs</strong><br><span class="muted">Le client personnalise son plat ; un choix obligatoire manquant bloque l&#39;ajout au panier.<br><i>Phase 4 ; les règles de modificateurs partagées (lot 2.3) sont réutilisables.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-03, RG-REST-08</td><td>2.3</td><td></td></tr><tr><td><strong>Panier et délai d&#39;inactivité</strong><br><span class="muted">Avertissement « Êtes-vous toujours là ? » puis retour à l&#39;accueil et purge du panier, sans aucun événement de vente ; compteur d&#39;abandon local.<br><i>Phase 4 ; le délai <code>inactivityTimeoutSeconds</code> est déjà dans le preset (lot 2.25).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-09</td><td></td><td></td></tr><tr><td><strong>Accessibilité</strong><br><span class="muted">Cibles ≥ 48 dp, contraste WCAG AA, grande police, interface compactée en bas d&#39;écran.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-13</td><td></td><td></td></tr></tbody></table><h2 id="paiement-commande" tabindex="-1">Paiement &amp; commande <a class="header-anchor" href="#paiement-commande" aria-label="Permalink to &quot;Paiement &amp; commande&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Paiement au comptoir</strong><br><span class="muted">La commande est créée « à payer », un ticket avec numéro et QR s&#39;imprime ; la caisse la retrouve par numéro ou QR et l&#39;encaisse en deux gestes.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-05</td><td></td><td></td></tr><tr><td><strong>Paiement au terminal et validation manuelle</strong><br><span class="muted">« Payez sur le terminal » avec confirmation manuelle tracée ou par webhook, rapprochement quotidien des validations manuelles avec le TPE.<br><i>Phase 4 ; les connecteurs de paiement et webhooks signés existent (lots 2.10 / 2.16) mais les intents depuis le kiosque restent ouverts.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-05, RG-KIOSK-07</td><td>2.10, 2.16</td><td></td></tr><tr><td><strong>Envoi en cuisine à la commande ou au paiement</strong><br><span class="muted">Selon le magasin, la commande part en cuisine dès sa confirmation ou une fois payée.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-06</td><td></td><td></td></tr><tr><td><strong>Numéros de retrait courts</strong><br><span class="muted">Numéro du jour (K-042) alloué séquentiellement par le hub local, préfixé par appareil sans hub (K1-042).<br><i>Phase 4 ; l&#39;allocation des numéros séquentiels par le hub est un reste ouvert du lot 2.6.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-08, RG-SYNC-25</td><td>2.6</td><td></td></tr><tr><td><strong>Commandes kiosque en cuisine</strong><br><span class="muted">La commande kiosque suit le même routage et les mêmes états qu&#39;une commande de salle, badgée KIOSQUE avec son numéro.<br><i>Phase 4 ; routage par poste et KDS déjà livrés pour la salle (lots 2.4 / 2.5).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-03, RG-REST-24</td><td></td><td></td></tr><tr><td><strong>Ticket kiosque et imprimante en panne</strong><br><span class="muted">Ticket au gros numéro de commande ; si l&#39;impression échoue, numéro affiché en grand ≥ 10 s et commande envoyée quand même.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-11</td><td></td><td></td></tr></tbody></table><h2 id="supervision" tabindex="-1">Supervision <a class="header-anchor" href="#supervision" aria-label="Permalink to &quot;Supervision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Supervision et heartbeat</strong><br><span class="muted">Chaque kiosque signale son état toutes les 60 s ; le back-office le marque « hors ligne » après 5 min sans signal.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-15</td><td></td><td></td></tr><tr><td><strong>Désactivation à distance</strong><br><span class="muted">La gérante désactive un kiosque : la commande en cours se termine puis l&#39;écran d&#39;indisponibilité s&#39;affiche, via le cloud et le hub.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-14</td><td></td><td></td></tr><tr><td><strong>Statistiques de conversion</strong><br><span class="muted">Sessions, commandes, abandons par étape, panier moyen, répartition sur place / à emporter par kiosque.<br><i>Phase 4 (restitution en spec 12).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-KIOSK-09, RG-KIOSK-15</td><td></td><td></td></tr></tbody></table><h2 id="variante-v2" tabindex="-1">Variante v2 <a class="header-anchor" href="#variante-v2" aria-label="Permalink to &quot;Variante v2&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Scan des articles par le client</strong><br><span class="muted">Variante retail : le client scanne ses articles à la caméra, les articles restreints passent au comptoir.<br><i>Hors périmètre v1 (variante v2 du kiosque).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-KIOSK-16</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Toute l&#39;app kiosque (phase 4) : mode verrouillé, parcours client, paiement au comptoir et au terminal, numéros de retrait, ticket kiosque.</li><li>Restrictions du rôle d&#39;appareil KIOSK côté serveur (403 FORBIDDEN_FOR_DEVICE_ROLE).</li><li>Allocation des numéros séquentiels par le hub local (reste du lot 2.6).</li><li>Intents de paiement depuis le kiosque et rapprochement des validations manuelles.</li><li>Téléversement des images des bannières et de l&#39;écran d&#39;accueil ; traduction des écrans kiosque.</li><li>Supervision des kiosques : heartbeat, désactivation à distance, statistiques de conversion.</li><li>Pourboire depuis le kiosque : hors périmètre du lot 2.9.</li></ul>',20)])])}const g=t(n,[["render",r]]);export{b as __pageData,g as default};
